def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = set()
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue

            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == bg and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            touches = set()
            for y, x in comp:
                if y == 0: touches.add("top")
                if y == h - 1: touches.add("bottom")
                if x == 0: touches.add("left")
                if x == w - 1: touches.add("right")

            fill = not touches
            if len(touches) == 1:
                r0 = min(y for y, x in comp)
                r1 = max(y for y, x in comp)
                c0 = min(x for y, x in comp)
                c1 = max(x for y, x in comp)
                walls = []
                if "top" not in touches:
                    walls.append(all(grid[r0-1][x] != bg for x in range(c0, c1+1)))
                if "bottom" not in touches:
                    walls.append(all(grid[r1+1][x] != bg for x in range(c0, c1+1)))
                if "left" not in touches:
                    walls.append(all(grid[y][c0-1] != bg for y in range(r0, r1+1)))
                if "right" not in touches:
                    walls.append(all(grid[y][c1+1] != bg for y in range(r0, r1+1)))
                fill = all(walls)

            if fill:
                for y, x in comp:
                    out[y][x] = 4

    return out
